    return sim.now + offsetAtSync + elapsed * driftPpm / 1_000_000
}

fun errorBoundMs(): Long {
    val elapsed = sim.now - syncedAt
    return boundAtSync + Math.ceilDiv(elapsed * maxDriftPpm, 1_000_000L)   // 1 ms + 6 ms after 30 s at 200 ppm
}

