fun writeWithCommitWait(value: String, done: (waitedMs: Long) -> Unit) {
    val stamp = clock.bounds().latest
    store.write(Write(value, stamp, name)) {
        val ackedAt = sim.now
        fun check() {
            if (clock.bounds().earliest > stamp) done(sim.now - ackedAt)
            else sim.after(1) { check() }
        }
        check()
    }
}
// latest: the true time is at most latest, so this stamp is not below any write that already happened
// (each of those was stamped at or below the true time when it was made, and waited until its stamp passed).
// earliest > stamp: the true time is now past the stamp, so any write that starts after done() is
// stamped with a latest that is past it too. Real-time order and stamp order agree.
